import{_ as t,o,c as a,ag as r}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Other/Intentional-departures-from-Civ-V.md","filePath":"Other/Intentional-departures-from-Civ-V.md"}'),i={name:"Other/Intentional-departures-from-Civ-V.md"};function n(s,e,l,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h2 id="water-melee-units-can-attack-land-units-on-shore" tabindex="-1">Water melee units can attack land units on shore <a class="header-anchor" href="#water-melee-units-can-attack-land-units-on-shore" aria-label="Permalink to &quot;Water melee units can attack land units on shore&quot;">​</a></h2><p>A result of a Discord poll. Water melee units in Civ V are considerably underpowered, so much so that even on maps with water they weren&#39;t considered competitive.</p><p>This change brings back an edge to water melee units that makes them worth building.</p><h2 id="workers-do-not-complete-an-improvement-on-the-same-turn-they-get-orders-to-work-on-it" tabindex="-1">Workers do not complete an improvement on the same turn - they get orders to work on it <a class="header-anchor" href="#workers-do-not-complete-an-improvement-on-the-same-turn-they-get-orders-to-work-on-it" aria-label="Permalink to &quot;Workers do not complete an improvement on the same turn - they get orders to work on it&quot;">​</a></h2><p>This allows players to assign workers to improve tiles, and then to reconsider and change improvement or move them elsewhere.</p><p>Building stuff takes time!</p><h2 id="forests-and-jungle-are-visible-1-tile-outside-visibility-range" tabindex="-1">Forests and Jungle are visible 1 tile outside visibility range <a class="header-anchor" href="#forests-and-jungle-are-visible-1-tile-outside-visibility-range" aria-label="Permalink to &quot;Forests and Jungle are visible 1 tile outside visibility range&quot;">​</a></h2><p>In Civ V, this is the behavior of Hills and Mountains, but not of Jungle and Forest.</p><p>And yet, Jungle and Forest <em>can block</em> Hills, and Hills+Forest can block Mountains from view - so they must be the same height!</p><p>This part of Civ V visibility makes no sense, considering the otherwise well-structured visibility logic, and we consider this to be a bug.</p><h2 id="great-warpath-does-not-provide-railroad-bonuses-for-connected-cities" tabindex="-1">Great Warpath does not provide railroad bonuses for connected cities <a class="header-anchor" href="#great-warpath-does-not-provide-railroad-bonuses-for-connected-cities" aria-label="Permalink to &quot;Great Warpath does not provide railroad bonuses for connected cities&quot;">​</a></h2><p>This is <a href="https://github.com/yairm210/Unciv/issues/12261" target="_blank" rel="noreferrer">a discrepancy in Civ V rules</a> - if all jungles are like roads, then they shouldn&#39;t be considered railroads for production purposes.</p><p>The idea is that if you can quickly transport goods with railroads that yields a production bonus - moving fast through jungles may be possible, but not with industrial amounts of goods.</p>',13)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
